const topic = $("Choose Topic").first().json.topic;
const tone = $("Choose Topic").first().json.tone;
const r = $json.response || '';

let post = 'L IA révolutionne Salesforce. Découvrez comment.';
let hashtags = ['#Salesforce', '#IA', '#DigitalTransformation'];

try {
  const jsonMatch = r.match(/\{[\s\S]*post[\s\S]*\}/);
  if (jsonMatch) {
    const p = JSON.parse(jsonMatch[0]);
    post = p.post || post;
    hashtags = p.hashtags || hashtags;
  }
} catch(e) {}

return [{json: {topic, tone, post, hashtags: hashtags.join(' '), generated_at: new Date().toISOString()}}];
